fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    a.into_iter()
        .map(|s| {
            if maxsplit == 0 {
                vec![s]
            } else {
                let mut parts = Vec::new();
                let mut remaining = s.as_str();
                let mut splits_done = 0;
                
                while splits_done < maxsplit {
                    if let Some(pos) = remaining.rfind(&sep) {
                        parts.push(remaining[pos + sep.len()..].to_string());
                        remaining = &remaining[..pos];
                        splits_done += 1;
                    } else {
                        break;
                    }
                }
                
                parts.push(remaining.to_string());
                parts.reverse();
                parts
            }
        })
        .collect()
}